import * as THREE from 'three';

export function createInteractionSystem() {
    const raycaster = new THREE.Raycaster();
    const clickables = new Map();
    const hovered = new Set();

    let pendingPrimaryAction = false;
    let activityPulse = false;

    function triggerPrimaryAction() {
        pendingPrimaryAction = true;
        activityPulse = true;
    }

    window.addEventListener('pointerdown', triggerPrimaryAction);
    window.addEventListener('keydown', (event) => {
        if (event.code === 'Space' || event.code === 'Enter') {
            triggerPrimaryAction();
        }
    });

    return {
        registerClickableTarget(object3D, handler) {
            clickables.set(object3D, handler);
        },
        unregisterClickableTarget(object3D) {
            clickables.delete(object3D);
            hovered.delete(object3D);
        },
        clearClickableTargets() {
            clickables.clear();
            hovered.clear();
        },
        isHovering(object3D) {
            return hovered.has(object3D);
        },
        consumeActivityPulse() {
            const value = activityPulse;
            activityPulse = false;
            return value;
        },
        update({ camera }) {
            hovered.clear();
            if (!clickables.size) {
                pendingPrimaryAction = false;
                return;
            }

            const targets = Array.from(clickables.keys());
            raycaster.setFromCamera(new THREE.Vector2(0, 0), camera);
            const hits = raycaster.intersectObjects(targets, false);

            if (!hits.length) {
                pendingPrimaryAction = false;
                return;
            }

            const topHit = hits[0].object;
            hovered.add(topHit);

            if (pendingPrimaryAction) {
                const handler = clickables.get(topHit);
                if (handler) {
                    handler();
                    activityPulse = true;
                }
            }

            pendingPrimaryAction = false;
        },
    };
}
